('op_6', 'Fulan F', 'Publikasi & Media', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=400&h=400&q=80', 'bidang', 'Dokumentasi visual, penulisan artikel, dan pengelolaan etalase kegiatan publik.', NULL, 2);--> statement-breakpoint

-- 2) kegiatan_publik (12 kegiatan terarsip)
INSERT OR IGNORE INTO `kegiatan_publik` (`id`, `slug`, `judul`, `excerpt`, `konten`, `cover_image`, `kategori`, `kategori_acara`, `tanggal`, `jam`, `lokasi`, `status`, `published_at`) VALUES
('kp_1', 'ngaji-rutin-selasa-malam', 'Ngaji Rutin Selasa Malam — bedah kitab & tanya jawab', 'Kajian mingguan yang santai tapi ngena. Materi terapan, bukan ceramah satu arah.', '<p>Kajian rutin Selasa malam — kitanya duduk melingkar, bukan baris. Tanya jawab bebas, pulang bawa 1 amalan yang langsung dipraktikin.</p>', 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=900&h=700&q=80', 'Sambung Rutin', 'sambung_rutin', '2026-09-02', '19:30', 'Musala Al-Falah', 'published', datetime('now')),
('kp_2', 'festival-anak-cengkareng', 'Festival Anak Cengkareng — lomba, bazaar, dan panggung kreasi', 'Seharian penuh buat anak-anak: lomba mewarnai, bazaar UMKM, dan panggung kreasi.', '<p>Festival tahunan merangkul cabe rawit dan pra-remaja se-Cengkareng.</p>', 'https://images.unsplash.com/photo-1531058020387-3be344556be6?auto=format&fit=crop&w=900&h=700&q=80', 'Lainnya', 'lainnya', '2026-09-15', '08:00', 'Lapangan Cengkareng', 'published', datetime('now')),
('kp_3', 'pelatihan-kepemimpinan-muda', 'Pelatihan Kepemimpinan Muda — dari anggota jadi penggerak', 'Workshop 1 hari: public speaking, manajemen konflik, dan cara bikin keputusan bareng.', '<p>Mencetak generasi muda yang berjiwa amanah, komunikatif, dan siap memimpin.</p>', 'https://images.unsplash.com/photo-1515187029135-18ee286d815b?auto=format&fit=crop&w=900&h=700&q=80', 'Pemantapan', 'pemantapan', '2026-09-20', '09:00', 'Aula Kecamatan', 'published', datetime('now')),
('kp_4', 'jalan-sehat-keluarga', 'Jalan Sehat Keluarga — start Masjid Al-Ikhlas, finish ngopi bareng', 'Rute 3 km keliling Cengkareng Timur. Doorprize sepeda, tapi yang penting silaturahmi.', '<p>Ajang keakraban bersama keluarga dan warga lingkungan.</p>', 'https://images.unsplash.com/photo-1552674605-db6ffd4facb5?auto=format&fit=crop&w=900&h=700&q=80', 'Keakraban', 'keakraban', '2026-10-04', '06:30', 'Masjid Al-Ikhlas', 'published', datetime('now')),
('kp_5', 'workshop-konten-kreatif-2', 'Workshop Konten Kreatif #2 — editing reels yang rapi & bermakna', 'Belajar ngedit reels & poster yang enak dilihat. Bawa HP aja, langsung praktek.', '<p>Pelatihan visual kreatif untuk syiar dakwah yang santun di media sosial.</p>', 'https://images.unsplash.com/photo-1516321497487-e288fb19713f?auto=format&fit=crop&w=900&h=700&q=80', 'Lainnya', 'lainnya', '2026-10-12', '10:00', 'Basecamp Gencar', 'published', datetime('now')),
('kp_6', 'sambung-akbar-q4', 'Sambung Akbar Q4 — temu 500 muda-mudi se-Cengkareng', 'Sambung terbesar tahun ini. Kajian tematik dan penguatan 6 Karakter Luhur.', '<p>Pertemuan akbar triwulan menyatukan visi dan kerukunan pemuda pemudi.</p>', 'https://images.unsplash.com/photo-1511795409834-ef04bbd61622?auto=format&fit=crop&w=900&h=700&q=80', 'Sambung Rutin', 'sambung_rutin', '2026-11-08', '19:00', 'Aula Cengkareng', 'published', datetime('now')),
('kp_7', 'kerja-bakti-cengkareng-bersih', 'Kerja Bakti Cengkareng Bersih — gotong royong bareng warga', 'Aksi bersih lingkungan kolaborasi muda-mudi, karang taruna, dan warga. Titik kumpul Masjid Al-Ikhlas.', '<p>Kerja bakti jadi ritual bulanan Gencar. Bukan seremonial — sapu, angkut, cat ulang pos ronda.</p>', 'https://images.unsplash.com/photo-1593113598332-cd288d649433?auto=format&fit=crop&w=900&h=700&q=80', 'Keakraban', 'keakraban', '2026-03-15', '07:00', 'Cengkareng Timur', 'published', datetime('now')),
('kp_8', 'sambung-rutin-akbar-maret', 'Sambung Rutin Akbar — 300 muda-mudi, satu frekuensi', 'Kajian tematik + sharing circle. Kurasi materi terapan, bukan ceramah satu arah.', '<p>Kajian mendalam mengupas aplikasi dalil dalam interaksi pergaulan zaman now.</p>', 'https://images.unsplash.com/photo-1527529482837-4698179dc6ce?auto=format&fit=crop&w=900&h=700&q=80', 'Sambung Rutin', 'sambung_rutin', '2026-03-08', '19:30', 'Aula Cengkareng', 'published', datetime('now')),
('kp_9', 'pemantapan-kader-intensif', 'Pemantapan Kader — dari panitia jadi penanggung jawab', 'Workshop intensif: public speaking, manajemen acara, dan etika kepanitiaan.', '<p>Pembekalan teknis kepanitiaan untuk pengurus muda-mudi generasi baru.</p>', 'https://images.unsplash.com/photo-1542744173-8e7e53415bb4?auto=format&fit=crop&w=900&h=700&q=80', 'Pemantapan', 'pemantapan', '2026-02-28', '13:00', 'Basecamp Gencar', 'published', datetime('now')),
('kp_10', 'futsal-persahabatan-antar-rw', 'Futsal Persahabatan Antar-RW — kalah menang tetap ngopi', 'Laga persahabatan yang ujungnya musyawarah. Olahraga sebagai jembatan silaturahmi.', '<p>Olahraga rutin menjaga kebugaran jasmani dan kerukunan pemuda.</p>', 'https://images.unsplash.com/photo-1431324155629-1a6deb1dec8d?auto=format&fit=crop&w=900&h=700&q=80', 'Keakraban', 'keakraban', '2026-02-20', '15:00', 'Lapangan Cengkareng', 'published', datetime('now')),
('kp_11', 'kelas-kreatif-desain-poster', 'Kelas Kreatif: Desain Poster Dakwah yang Nggak Ngebosenin', 'Belajar Canva, tipografi, dan hierarki visual. Output langsung jadi poster kegiatan.', '<p>Workshop desain grafis untuk tim publikasi media sosial.</p>', 'https://images.unsplash.com/photo-1561070791-2526d30994b5?auto=format&fit=crop&w=900&h=700&q=80', 'Lainnya', 'lainnya', '2026-02-12', '10:00', 'Ruang Kreatif', 'published', datetime('now')),
('kp_12', 'bakti-sosial-ramadhan-berbagi', 'Bakti Sosial Ramadhan — paket sembako & takjil on the road', 'Distribusi 200 paket + takjil keliling. Donasi transparan, laporan publik.', '<p>Berbagi kebahagiaan di bulan suci bersama kaum dhuafa dan musafir.</p>', 'https://images.unsplash.com/photo-1488521787991-ed7bbaae773c?auto=format&fit=crop&w=900&h=700&q=80', 'Keakraban', 'keakraban', '2026-02-02', '16:00', 'Cengkareng Barat', 'published', datetime('now'));--> statement-breakpoint

-- 3) artikel & berita (12 artikel publik)
INSERT OR IGNORE INTO `artikel` (`id`, `slug`, `judul`, `ringkasan`, `konten`, `cover_image`, `kategori`, `tipe`, `status`, `author_id`, `published_at`) VALUES
('art_1', 'cara-bikin-kegiatan-yang-orang-mau-datang', 'Cara bikin kegiatan yang orang mau datang (tanpa spam broadcast)', 'Rumus sederhana: janji jelas, tempat jelas, pulang bawa cerita.', '<p>Kegiatan yang bermakna berakar dari niat ikhlas dan persiapan matang. Jangan hanya broadcast berulang-ulang, buatlah agenda yang menjawab kebutuhan jamaah muda-mudi.</p>', 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?auto=format&fit=crop&w=700&h=480&q=80', 'Tuntunan Ibadah', 'artikel', 'published', 'd2c461fc-b1b8-4320-86b6-c6d2b0e7b2f1', datetime('now')),
('art_2', 'kenapa-dokumentasi-kegiatan-itu-penting', 'Kenapa dokumentasi kegiatan itu penting — bukan buat pamer', 'Arsip yang rapi bikin regenerasi nggak mulai dari nol.', '<p>Dokumentasi adalah ikhtiar merawat sejarah pembinaan. Catatan yang rapi akan menjadi rujukan pengurus generasi berikutnya.</p>', 'https://images.unsplash.com/photo-1454165205744-3b78555e5572?auto=format&fit=crop&w=700&h=480&q=80', 'Kisah', 'artikel', 'published', 'd2c461fc-b1b8-4320-86b6-c6d2b0e7b2f1', datetime('now')),
('art_3', 'ngelola-komunitas-tanpa-burnout', 'Ngelola komunitas tanpa burnout: sistem kecil yang jalan terus', 'Checklist, rotasi, dan dokumentasi — tiga hal yang menyelamatkan panitia.', '<p>Beban kepengurusan harus dipikul bersama secara rukun dan kompak. Hindari bertumpu pada satu orang saja.</p>', 'https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=700&h=480&q=80', 'Info Kesehatan', 'artikel', 'published', 'd2c461fc-b1b8-4320-86b6-c6d2b0e7b2f1', datetime('now')),
('art_4', 'briefing-panitia-15-menit-yang-efektif', 'Briefing panitia 15 menit yang efektif — bukan rapat 2 jam', 'Format briefing yang bikin semua tau tugasnya sebelum acara mulai.', '<p>Briefing singkat berfokus pada eksekusi lapangan, koordinasi penanggung jawab, dan doa bersama.</p>', 'https://images.unsplash.com/photo-1515187029135-18ee286d815b?auto=format&fit=crop&w=700&h=480&q=80', 'Berita', 'berita', 'published', 'd2c461fc-b1b8-4320-86b6-c6d2b0e7b2f1', datetime('now')),
('art_5', 'desain-poster-dakwah-yang-nggak-norak', 'Desain poster dakwah yang nggak norak — hierarki visual 101', 'Tipografi, kontras, dan whitespace yang bikin poster kebaca, bukan rame.', '<p>Estetika visual adalah bagian dari adab menyampaikan kebaikan dengan cara yang indah dan mudah dipahami.</p>', 'https://images.unsplash.com/photo-1561070791-2526d30994b5?auto=format&fit=crop&w=700&h=480&q=80', 'Tafsir', 'artikel', 'published', 'd2c461fc-b1b8-4320-86b6-c6d2b0e7b2f1', datetime('now')),
('art_6', 'cara-nulis-laporan-kegiatan-yang-dibaca', 'Cara nulis laporan kegiatan yang dibaca — bukan diarsip doang', 'Struktur laporan 1 halaman yang bikin generasi next ngerti konteksnya.', '<p>Laporan pertanggungjawaban yang transparan adalah bentuk amanah dan keterbukaan dalam berorganisasi.</p>', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?auto=format&fit=crop&w=700&h=480&q=80', 'Tuntunan Ibadah', 'artikel', 'published', 'd2c461fc-b1b8-4320-86b6-c6d2b0e7b2f1', datetime('now')),
('art_7', 'rekrut-panitia-baru-tanpa-maksa', 'Rekrut panitia baru tanpa maksa — sistem kaderisasi pelan-pelan', 'Cara ngajak yang bikin orang mau, bukan karena nggak enak nolak.', '<p>Pendekatan personal dan keteladanan akhlak lebih efektif dalam merangkul rekan-rekan muda-mudi.</p>', 'https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=700&h=480&q=80', 'Kisah', 'artikel', 'published', 'd2c461fc-b1b8-4320-86b6-c6d2b0e7b2f1', datetime('now')),
('art_8', 'mc-acara-komunitas-yang-nggak-kaku', 'MC acara komunitas yang nggak kaku — ngobrol, bukan pidato', 'Teknik public speaking santai yang bikin audiens betah dengerin.', '<p>Membawakan acara dengan hangat menciptakan suasana akrab dan menyenangkan bagi seluruh hadirin.</p>', 'https://images.unsplash.com/photo-1475721027785-f74eccf877e2?auto=format&fit=crop&w=700&h=480&q=80', 'Info Kesehatan', 'artikel', 'published', 'd2c461fc-b1b8-4320-86b6-c6d2b0e7b2f1', datetime('now')),
('art_9', 'kelola-kas-komunitas-transparan', 'Kelola kas komunitas biar transparan — template laporan keuangan', 'Pencatatan sederhana yang bikin semua anggota tau uangnya kemana.', '<p>Kejujuran dan ketelitian dalam mengelola dana infaq adalah pilar utama kepercayaan bersama.</p>', 'https://images.unsplash.com/photo-1553729459-efe14ef6055d?auto=format&fit=crop&w=700&h=480&q=80', 'Berita', 'berita', 'published', 'd2c461fc-b1b8-4320-86b6-c6d2b0e7b2f1', datetime('now')),
('art_10', 'dokumentasi-foto-yang-storytelling', 'Dokumentasi foto yang storytelling — bukan cuma foto bareng', 'Angle, momen, dan sequencing yang bikin foto kegiatan bercerita.', '<p>Abadikan momen kebersamaan dan ekspresi tulus saat bergotong royong atau menuntut ilmu.</p>', 'https://images.unsplash.com/photo-1452587925148-ce544e77e70d?auto=format&fit=crop&w=700&h=480&q=80', 'Tafsir', 'artikel', 'published', 'd2c461fc-b1b8-4320-86b6-c6d2b0e7b2f1', datetime('now')),
('art_11', 'follow-up-setelah-kegiatan', 'Follow-up setelah kegiatan — biar nggak hilang momentum', 'Apa yang dilakuin 24 jam setelah acara biar efeknya nggak berhenti.', '<p>Evaluasi dan apresiasi kepada seluruh panitia menjaga semangat kebersamaan tetap menyala.</p>', 'https://images.unsplash.com/photo-1516321497487-e288fb19713f?auto=format&fit=crop&w=700&h=480&q=80', 'Tuntunan Ibadah', 'artikel', 'published', 'd2c461fc-b1b8-4320-86b6-c6d2b0e7b2f1', datetime('now')),
('art_12', 'kolaborasi-antar-komunitas', 'Kolaborasi antar komunitas — saingan jadi barengan', 'Cara ngajak komunitas lain kerja bareng tanpa rebutan panggung.', '<p>Sinergi positif dengan elemen kemasyarakatan dan kepemudaan lingkungan sekitar.</p>', 'https://images.unsplash.com/photo-1527529482837-4698179dc6ce?auto=format&fit=crop&w=700&h=480&q=80', 'Berita', 'berita', 'published', 'd2c461fc-b1b8-4320-86b6-c6d2b0e7b2f1', datetime('now'));--> statement-breakpoint

