-- 5) settings (tentang_json resmi)
INSERT OR REPLACE INTO `settings` (`key`, `value`, `updated_at`) VALUES
('tentang_json', '{"hero":{"kicker":"Etalase Muda-Mudi Cengkareng","title":"Wadah kebersamaan &","titleEm":"pembinaan generus","titleEnd":"di Cengkareng.","lead":"Ruang dokumentasi resmi kegiatan, syiar nilai budi pekerti, dan etalase karya generasi muda LDII Daerah Cengkareng — dari tingkat kelompok hingga daerah.","ctaPrimary":{"label":"Arsip kegiatan","href":"/kegiatan"},"ctaSecondary":{"label":"Struktur Pengurus","href":"/pengurus"},"meta":[{"icon":"sparkles","text":"Etalase Dokumentasi"},{"icon":"users","text":"Daerah Cengkareng"},{"icon":"calendar","text":"Pembinaan Berkelanjutan"}],"ghostText":"LDII","image":"https://images.unsplash.com/photo-1511795409834-ef04bbd61622?auto=format&fit=crop&w=900&h=900&q=80","floatQuote":"“Rukun, kompak, dan kerja sama yang baik.”","floatAttribution":"— Karakter Luhur"},"letter":{"image":"https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=700&h=800&q=80","caption":"Dokumentasi pembinaan berjenjang: dari kelompok, desa, hingga tingkat daerah Cengkareng.","heading":"Dinamika Pembinaan & Sinergi Generus","dropcapText":"Pembinaan generasi muda di Cengkareng berakar dari pengajian rutin kelompok hingga kegiatan terpadu tingkat daerah. Setiap jenjang usia dirangkul melalui materi Al-Qur''an dan Al-Hadits yang aplikatif serta pembiasaan akhlak mulia.","paragraph2":"Tujuan utama kami adalah mencetak generasi penerus yang memiliki Tri Sukses: alim dan faqih dalam ilmu agama, berakhlakul karimah dalam pergaulan, serta mandiri dalam mengarungi kehidupan bermasyarakat.","paragraph3":"Laman web ini dihadirkan sebagai etalase publik yang transparan dan rapi. Seluruh dokumentasi kegiatan, artikel kepemudaan, dan karya warga tersaji agar menjadi inspirasi positif bagi sesama dan masyarakat luas.","quote":"“Membina generus bukan sekadar program tahunan, melainkan ikhtiar berkesinambungan mencetak insan yang bermanfaat bagi agama, nusa, dan bangsa.”","quoteCite":"— Pembina Muda-Mudi Cengkareng"},"manifesto":{"heading":"Pondasi Pembinaan: Tri Sukses Generus","subheading":"Tiga target utama yang senantiasa ditanamkan dalam setiap kegiatan muda-mudi.","cards":[{"num":"01","title":"Alim & Faqih","body":"Paham Al-Qur''an dan Al-Hadits secara mendalam serta mengamalkannya dalam kehidupan sehari-hari.","proof":"Lihat kegiatan pembinaan →","href":"/kegiatan","isInk":true},{"num":"02","title":"Berakhlakul Karimah","body":"Mempraktikkan budi pekerti luhur, beradab, santun kepada yang lebih tua, dan menyayangi sesama.","proof":"Baca artikel literasi →","href":"/artikel"},{"num":"03","title":"Mandiri & Berdaya","body":"Memiliki keahlian nyata, etos kerja tangguh, dan kesiapan menghadapi tantangan zaman.","proof":"Cerita generus →","href":"#cerita"}]},"chronicle":{"heading":"Pilar & Dimensi Pembinaan","subheading":"Fokus pengembangan potensi generasi muda se-Daerah Cengkareng.","items":[{"year":"Pembinaan","title":"Kajian & Sambung Rutin","desc":"Pengajian Al-Qur''an dan Al-Hadits berjenjang dari usia cabe rawit, pra-remaja, hingga muda-mudi di setiap kelompok.","image":"https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=300&h=300&q=80"},{"year":"Karakter","title":"6 Karakter Luhur","desc":"Penanaman tabiat jujur, amanah, hemat, rukun, kompak, dan kerja sama yang baik dalam interaksi harian.","image":"https://images.unsplash.com/photo-1527529482837-4698179dc6ce?auto=format&fit=crop&w=300&h=300&q=80"},{"year":"Kemandirian","title":"Skill & Kemandirian","desc":"Pelatihan keterampilan wirausaha, teknologi, desain, hingga keputrian untuk mencetak generus mandiri.","image":"https://images.unsplash.com/photo-1515187029135-18ee286d815b?auto=format&fit=crop&w=300&h=300&q=80"},{"year":"Etalase","title":"Dokumentasi & Syiar","desc":"Ruang publik untuk mengarsipkan karya, dinamika positif, dan kontribusi nyata generus di Cengkareng.","image":"https://images.unsplash.com/photo-1511795409834-ef04bbd61622?auto=format&fit=crop&w=300&h=300&q=80"}]},"voices":{"heading":"Cerita dari Lapangan","subheading":"Refleksi nyata dari muda-mudi, pembina, dan penggerak kegiatan di Cengkareng.","stories":[{"nama":"Rafi — Generus Cengkareng Barat","peran":"Peserta Sambung Rutin","angkatan":"Muda-Mudi Cengkareng","foto":"https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=400&h=400&q=80","quote":"Sambung rutin bukan cuma nambah kepahaman agama, tapi juga tempat sharing ilmu praktis dan saling nguatin antar pemuda.","konteks":"Aktif membantu pencatatan notulensi dan koordinasi keakraban di tingkat kelompok."},{"nama":"Pak Bambang — Pembina Daerah","peran":"Dewan Penasihat / Pembina","angkatan":"Daerah Cengkareng","foto":"https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=400&h=400&q=80","quote":"Generus yang berhasil adalah yang seimbang: paham agama, berakhlak mulia, dan punya keahlian mandiri untuk masa depannya.","konteks":"Mendampingi regenerasi kepengurusan muda-mudi agar terus kompak dan berkesinambungan."},{"nama":"Dimas — Koordinator Kegiatan","peran":"Pengurus Harian","angkatan":"Muda-Mudi Cengkareng Timur","foto":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=400&h=400&q=80","quote":"Kunci kegiatan generus itu rukun dan kompak. Dari kepanitiaan kecil sampai acara akbar, yang penting kerja sama yang baik.","konteks":"Mengkoordinasikan tim logistik dan teknis lapangan di setiap agenda daerah."}]},"stats":{"items":[{"target":48,"label":"Kegiatan Terdokumentasi","variant":"ink"},{"target":1.2,"decimals":1,"suffix":"k","label":"Muda-Mudi Terbina","variant":"default"},{"target":36,"label":"Artikel & Risalah","variant":"lime"},{"target":12,"label":"Pengurus & Koordinator","variant":"default"}],"ctaText":"Jelajahi arsip kegiatan terlaksana","ctaHref":"/kegiatan"},"cta":{"heading":"Etalase & Informasi Kepengurusan","body":"Untuk koordinasi internal, informasi jadwal kegiatan tingkat daerah, atau pertanyaan seputar dokumentasi publik generus Cengkareng, silakan hubungi perwakilan pengurus.","primaryLabel":"Dokumentasi Kegiatan","primaryHref":"/kegiatan","secondaryLabel":"Pengurus Daerah","secondaryHref":"/pengurus","image":"https://images.unsplash.com/photo-1552674605-db6ffd4facb5?auto=format&fit=crop&w=700&h=500&q=80"}}', datetime('now'));
